"""Twenty-mark final-paper blueprint, with original values and explicit manual rubrics."""
from bank_core import *
from diagrams import line_svg,solid_svg,triangle_svg
MARKS=[1,1,1,1.25,.5,1.25,1.25,1.75,2.25,2,1,2,1.25,1,1,.5]
PAGES={**{i:1 for i in [1,2,3]},**{i:2 for i in [4,5,6,7]},**{i:3 for i in [8,9,10,11]},**{i:4 for i in [12,13,14,15,16]}}
GROUP_TITLES=['درست یا نادرست','تکمیل‌کردنی','گزینهٔ صحیح','نمایش و عملیات مجموعه‌ها','احتمال','عددهای حقیقی و قدر مطلق','اثبات و تشابه','توان، ریشه و رادیکال','اتحاد، تجزیه و نامعادله','نمودار و معادلهٔ خط','دستگاه معادله‌های خطی','عبارت‌های گویا','تقسیم چندجمله‌ای‌ها','مساحت کره','دوران و حجم','گستردهٔ هرم']
def questions(level=1,v=1):
 rows=[];a=2+v+level;k=level+v;r=2+v;u=3+v
 def add(g,part,ch,marks,typ,prompt,answer,feedback,options=None,steps=None,check=None,aliases=None,diagram=None,drawing=False):
  qid=f'f00-final-l{level}-v{v}-p{part:02d}-q{g:02d}'
  rows.append(dict(id=qid,family=f'final-q{g:02d}-p{part:02d}',group=g,part=part,page=PAGES[g],marks=marks,chapterNumber=ch,chapter='فصل '+str(ch)+': '+CHAPTERS[ch],grade=9,book='ریاضی نهم',lesson=GROUP_TITLES[g-1],topic=GROUP_TITLES[g-1],objective=GROUP_TITLES[g-1],level=level,difficulty=LEVELS[level-1],type=typ,prompt=prompt,answer=str(answer),feedback=feedback,options=options or [],rubric=[dict(id='step'+str(i+1),text=text,marks=point) for i,(text,point) in enumerate(steps or [])],check=check,aliases=aliases or [],diagram=diagram,drawing=drawing,variant=v,origin='تألیفی؛ فرم و بارم مطابق الگوی واقعی پایان سال'))
 def auto(g,p,ch,marks,prompt,answer,expr,typ='short',options=None,aliases=None):add(g,p,ch,marks,typ,prompt,answer,'پاسخ با تعریف و داده‌های همین بخش کنترل می‌شود.',options,check={'kind':'number','expression':expr} if typ=='short' else {'kind':'reviewed-fact','fact':'final'},aliases=aliases)
 def manual(g,p,ch,marks,prompt,answer,steps,expr=None,diagram=None,drawing=False):
  assert sum(x[1] for x in steps)==marks
  add(g,p,ch,marks,'essay',prompt,answer,'پاسخ نمونه و بارم مرحله‌ها را با نوشته یا رسم خودت مقایسه کن.',steps=steps,check={'kind':'manual-review','expression':expr},diagram=diagram,drawing=drawing)
 # Page one: three one-mark groups, each with four quarter-mark parts.
 auto(1,1,2,.25,('اشتراک' if v%2 else 'اجتماع')+' مجموعهٔ عددهای گویا و گنگ تهی است.','درست' if v%2 else 'نادرست','0','tf')
 auto(1,2,3,.25,'محل برخورد ارتفاع‌های '+('هر مثلث، همیشه داخل مثلث است.' if v%2 else 'مثلث منفرجه‌الزاویه، بیرون مثلث است.'),'نادرست' if v%2 else 'درست','0','tf')
 auto(1,3,4,.25,f'حاصل {k}^(−2) برابر '+('1/' if v%2 else '−1/')+f'{k*k} است.','درست' if v%2 else 'نادرست','0','tf')
 auto(1,4,2,.25,f'اگر a−b=−{v} باشد، آنگاه '+('a<b' if v%2 else 'a>b')+' است.','درست' if v%2 else 'نادرست','0','tf')
 auto(2,1,1,.25,f'تعداد اعضای مجموعهٔ {{{a},{a+1},{a},{a+2}}} برابر … است.',3,'Integer(3)')
 auto(2,2,5,.25,f'درجهٔ {a}x²y^{k} نسبت به y برابر … است.',k,f'degree({a}*x**2*y**{k},y)')
 auto(2,3,5,.25,'اگر حاصل ضرب چند عدد صفر باشد، حداقل یکی از عامل‌ها برابر … است.',0,'Integer(0)')
 auto(2,4,6,.25,f'خط y={a} موازی محور … است.','طول‌ها','0','text',aliases=['طولها','x','ایکس','افقی'])
 auto(3,1,7,.25,'کدام عبارت گویا نیست؟','√x',['0'],'mcq',options=['√x','1/(x+1)','x²−1','(x+2)/(x−3)'])
 auto(3,2,8,.25,'حجم کره به شعاع R کدام است؟','(4/3)πR³','0','mcq',options=['(4/3)πR³','4πR²','πR²','(1/3)πR³'])
 cross=4+v+level
 auto(3,3,6,.25,f'هزینهٔ دو طرح A={a}+{k}x و B={a+cross}+{k-1}x است؛ تا قبل از کدام x، طرح A ارزان‌تر است؟',str(cross),'0','mcq',options=list(map(str,[cross,cross+1,cross+3,cross-1])))
 auto(3,4,8,.25,'یک استوانهٔ قائم روی قاعدهٔ دایره‌ای خود ایستاده است؛ نمای دقیق از بالا کدام است؟','دایره','0','mcq',options=['دایره','مثلث','مربع','نیم‌دایره'])
 # Page two: sets, probability, real numbers, proof and similarity.
 A={a,a+1,a+2};B={a+1,a+2,a+3}
 manual(4,1,1,.75,f'A={roster(A)} و B={roster(B)}؛ هر دو مجموعهٔ A∪B و A−B را بنویس.',f'A∪B={roster(A|B)} و A−B={roster(A-B)}',[('اعضای اجتماع بدون تکرار',.5),('اعضای تفاضل با جهت درست',.25)])
 auto(4,2,1,.25,f'نماد مناسب در {a} … A برای A={roster(A)} کدام است؟','∈','0','text')
 add(4,3,1,.25,'set',f'مجموعهٔ عددهای طبیعی x با 0<x<{a} را با اعضا بنویس.',roster(range(1,a)),'کران‌ها بازند؛ صفر در این بازه قرار ندارد.',check={'kind':'set','expressions':list(map(str,range(1,a)))})
 manual(5,1,1,.5,f'از کارت‌های یکسان شمارهٔ 1 تا {3*a} یکی با شانس برابر انتخاب می‌کنیم؛ احتمال مضرب 3 بودن را با فرمول بنویس.','P(A)=n(A)/n(S)='+str(a)+'/'+str(3*a)+'=1/3',[('تعداد حالت مطلوب و کل حالت‌ها',.25),('نسبت و پاسخ ساده‌شده',.25)],expr='Rational(1,3)')
 exact=abs(F(2,level+1)-F(3+v,2))
 auto(6,1,2,.75,f'اگر a=1/{level+1} و b={frac(3+v,2)} باشد، |2a−b| چند است؟',exact,f'Abs(2*Rational(1,{level+1})-Rational({3+v},2))')
 manual(6,2,2,.5,f'کدام مجموعه همهٔ نقطه‌های بازهٔ بستهٔ 0 تا {a} را نشان می‌دهد و چرا؟ A={roster(range(a+1))} یا B={{x∈ℝ | 0≤x≤{a}}}.','B؛ چون بازهٔ حقیقی همهٔ عددهای بین دو کران از جمله کسرها و گنگ‌ها را شامل می‌شود، نه فقط صحیح‌ها. ',[('انتخاب B',.25),('توضیح تفاوت بازه و فهرست صحیح‌ها',.25)])
 manual(7,1,3,.75,'از نقطهٔ P بیرون دایرهٔ مرکز O، دو مماس PA و PB رسم شده است؛ با هم‌نهشتی نشان بده PA=PB.','OA=OB شعاع‌اند؛ زاویه‌های OAP و OBP قائمه و OP وتر مشترک است؛ هم‌نهشتی به وتر و ضلع می‌دهد PA=PB.',[('شعاع‌های برابر و عمود بودن بر مماس',.25),('وتر مشترک و معیار هم‌نهشتی',.25),('تناظر و نتیجهٔ PA=PB',.25)])
 auto(7,2,3,.5,f'دو مثلث متشابه‌اند؛ ضلع‌های متناظر اول {a} و {k*a} و ضلع دیگر کوچک {a+2} است؛ ضلع متناظر بزرگ چند است؟',k*(a+2),f'({k*a}/{a})*{a+2}')
 # Page three: exact groups and subpart marks of the selected final-paper form.
 auto(8,1,4,.5,f'حاصل ∛{(k+1)**3*a}÷∛{a} چند است؟',k+1,f'real_root({(k+1)**3*a},3)/real_root({a},3)')
 manual(8,2,4,.75,f'حاصل √{3*(a+1)**2}−√{3*a*a} را ساده کن.','√3',[('تشخیص عامل مربع کامل اول',.25),('تشخیص عامل مربع کامل دوم',.25),('تفریق ضریب‌ها و پاسخ',.25)],expr=f'sqrt({3*(a+1)**2})-sqrt({3*a*a})')
 manual(8,3,4,.5,f'مخرج کسر {k}/√{a} را گویا کن.',f'{k}√{a}/{a}',[('ضرب صحیح صورت و مخرج در √'+str(a),.25),('ساده‌سازی حاصل',.25)],expr=f'{k}/sqrt({a})')
 manual(9,1,5,1,f'با کمک اتحاد، حاصل (x+{a})(x−{a+1}) را به صورت چندجمله‌ای بنویس.',f'x²−x−{a*(a+1)}',[('ضرب جمله‌های x',.25),('دو جملهٔ میانی با علامت درست',.25),('ضرب ثابت‌ها',.25),('ساده‌سازی نهایی',.25)],expr=f'(x+{a})*(x-{a+1})')
 manual(9,2,5,.5,f'x²−{a*a} را تجزیه کن.',f'(x−{a})(x+{a})',[('شناخت تفاضل دو مربع',.25),('دو عامل مزدوج درست',.25)],expr=f'x**2-{a*a}')
 manual(9,3,5,.75,f'نامعادلهٔ −{k}x+{a}≤{a+k*(v+1)} را حل و مجموعهٔ جواب را بنویس.',f'x≥−{v+1}',[('انتقال ثابت و ساده‌سازی',.25),('تقسیم منفی و عوض شدن جهت',.25),('مجموعهٔ جواب و کران بسته',.25)])
 m=1+level;c=1+v
 manual(10,1,6,1,'از نمودار، مختصات دو نقطهٔ دارای طول صفر و یک و سپس شیب خط را مشخص کن.',f'(0,{c}) و (1,{m+c})؛ شیب {m}',[('خواندن نقطهٔ طول صفر',.25),('خواندن نقطهٔ طول یک',.25),('فرمول نسبت تغییرها',.25),('شیب درست',.25)],diagram=line_svg(m,c))
 manual(10,2,6,.5,'معادلهٔ همان خط رسم‌شده در بخش قبل را بنویس.',f'y={m}x+{c}',[('شیب درست در معادله',.25),('عرض از مبدأ و فرم معادله',.25)])
 auto(10,3,6,.5,f'خط y={k}x−{a} در چه عرضی محور y را قطع می‌کند؟',-a,f'-{a}')
 X=1+v;Y=2+level
 manual(11,1,6,1,f'دستگاه 2x+y={2*X+Y} و x−y={X-Y} را حل کن و هر دو مجهول را بنویس.',f'x={X} و y={Y}',[('حذف یا جایگذاری معتبر',.25),('حل مجهول نخست',.25),('یافتن مجهول دوم',.25),('کنترل جواب در هر دو معادله',.25)],expr=f'{X}+{Y}')
 # Page four: rational expressions, polynomial division and geometry.
 add(12,1,7,.5,'set',f'مقدارهای تعریف‌نشدهٔ {k}/[x(x−{a})] را بنویس.',roster([0,a]),'هر عامل مخرج را جدا صفر کن.',check={'kind':'set','expressions':['0',str(a)]})
 manual(12,2,7,.75,f'برای مقدارهای مجاز، [(x²−{a*a})/(x+1)]×[(x+1)/(x−{a})] را ساده و محدودیت‌ها را بنویس.',f'x+{a}؛ x≠−1 و x≠{a}',[('تجزیهٔ صورت',.25),('حذف عامل‌ها و پاسخ',.25),('حفظ هر دو مقدار ممنوع',.25)],expr=f'(x**2-{a*a})/(x+1)*(x+1)/(x-{a})')
 manual(12,3,7,.75,f'طول و عرض مستطیل به‌ترتیب x/(x−{a}) و {k}/(x−{a}) است؛ x>{a}. محیط را بر حسب x ساده کن.',f'2(x+{k})/(x−{a})',[('فرمول دو برابر مجموع طول و عرض',.25),('جمع کسرهای هم‌مخرج',.25),('پاسخ ساده و توجه به دامنه',.25)],expr=f'2*(x/(x-{a})+{k}/(x-{a}))')
 R=2+level;C=2+v
 manual(13,1,7,1.25,f'تقسیم x²+{C-a}x+({R-a*C}) بر x−{a} را انجام بده؛ خارج‌قسمت و باقی‌مانده و رابطهٔ کنترل را بنویس.',f'خارج‌قسمت x+{C}؛ باقی‌مانده {R}؛ مقسوم=(x−{a})(x+{C})+{R}',[('نخستین جملهٔ خارج‌قسمت',.25),('ضرب و تفریق مرحلهٔ نخست',.25),('جملهٔ دوم و ادامهٔ تقسیم',.25),('باقی‌ماندهٔ درست',.25),('رابطهٔ درستی تقسیم',.25)],expr=f'rem(x**2+{C-a}*x+({R-a*C}),x-{a},x)')
 manual(14,1,8,1,f'برای روکش یک توپ با قطر {2*r} سانتی‌متر، بدون اتلاف یا هم‌پوشانی چند سانتی‌متر مربع ماده لازم است؟ پاسخ را بر حسب π بنویس.',f'{4*r*r}π سانتی‌متر مربع',[('نصف کردن قطر و یافتن شعاع',.25),('فرمول مساحت کره',.25),('جایگذاری و محاسبهٔ ضریب',.25),('پاسخ با π و واحد مربع',.25)],expr=f'4*pi*{r}**2',diagram=solid_svg('sphere'))
 auto(15,1,8,.25,f'مثلث قائم با ضلع‌های قائمه {3*k} و {4*k} را حول ضلع {4*k} دوران می‌دهیم؛ نام حجم حاصل چیست؟','مخروط','0','text',aliases=['مخروط قائم'])
 manual(15,2,8,.75,f'حجم همان جسم را با π=3 حساب کن.','شعاع '+str(3*k)+' و ارتفاع '+str(4*k)+' است؛ حجم '+str(36*k**3)+' سانتی‌متر مکعب است.',[('شعاع و ارتفاع متناظر درست',.25),('فرمول و جایگذاری حجم مخروط',.25),('محاسبه و واحد مکعب',.25)],expr=f'3*({3*k})**2*{4*k}/3')
 manual(16,1,8,.5,'یک گستردهٔ معتبر از هرم منتظمِ قاعده‌مربع رسم کن؛ قاعده و وجه‌های جانبی را مشخص کن.','یک مربع با چهار مثلث متساوی‌الساقین هم‌اندازه که هرکدام به یک ضلع مربع وصل باشند.',[('قاعدهٔ مربع و چهار وجه سازگار',.25),('اتصال درست و بدون هم‌پوشانی',.25)],drawing=True)
 assert len({q['id'] for q in rows})==len(rows)
 for g,marks in enumerate(MARKS,1):assert sum(q['marks'] for q in rows if q['group']==g)==marks,(g,marks)
 assert sum(q['marks'] for q in rows)==20
